css:
:root {
  --bg: #f5f7fa;
  --panel: #ffffff;
  --text: #1f2937;
  --muted: #64748b;
  --subtle: #94a3b8;
  --line: #e2e8f0;
  --nav: #102a43;
  --nav-text: #d9e2ec;
  --blue: #2563eb;
  --blue-soft: #eff6ff;
  --green: #15803d;
  --green-soft: #f0fdf4;
  --red: #b91c1c;
  --red-soft: #fef2f2;
  --amber: #a16207;
  --amber-soft: #fffbeb;
  --shadow: 0 1px 2px rgba(15, 23, 42, .04);
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--text); font: 14px/1.45 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif; }
button, select { font: inherit; }
.app { min-height: 100vh; display: grid; grid-template-columns: 224px minmax(0, 1fr); }
.sidebar { background: var(--nav); color: var(--nav-text); padding: 22px 14px; }
.brand { display: flex; gap: 10px; align-items: center; padding: 0 11px 28px; color: #fff; font-size: 16px; font-weight: 650; letter-spacing: -.1px; }
.brand-mark { width: 28px; height: 28px; border-radius: 5px; background: #2f6fbb; display: grid; place-items: center; font-weight: 700; font-size: 13px; }
.section-label { color: #9fb3c8; font-size: 10px; font-weight: 700; letter-spacing: .08em; margin: 13px 11px 8px; text-transform: uppercase; }
.nav-list { list-style: none; padding: 0; margin: 0; }
.nav-list li { margin: 3px 0; }
.nav-link { display: flex; align-items: center; gap: 11px; border-radius: 4px; color: var(--nav-text); padding: 9px 11px; text-decoration: none; }
.nav-link.active { background: #1f4b72; color: #fff; font-weight: 600; }
.nav-icon { width: 17px; text-align: center; color: #a9bdd1; font-size: 14px; }
.nav-link.active .nav-icon { color: #fff; }
.main { min-width: 0; }
.topbar { height: 65px; background: var(--panel); border-bottom: 1px solid var(--line); display: flex; align-items: center; justify-content: space-between; padding: 0 32px; }
.breadcrumbs { color: var(--muted); font-size: 13px; }
.breadcrumbs strong { color: var(--text); font-weight: 600; }
.top-actions { display: flex; align-items: center; gap: 18px; }
.icon-button { border: 0; background: transparent; color: var(--muted); font-size: 17px; padding: 3px; }
.profile { display: flex; gap: 9px; align-items: center; border-left: 1px solid var(--line); padding-left: 18px; }
.avatar { width: 30px; height: 30px; border-radius: 50%; background: #dbeafe; color: #1e40af; display: grid; place-items: center; font-weight: 700; font-size: 12px; }
.profile-name { font-size: 13px; font-weight: 600; }
.profile-role { font-size: 11px; color: var(--muted); }
.content { max-width: 1440px; margin: 0 auto; padding: 28px 32px 40px; }
.page-heading { display: flex; justify-content: space-between; gap: 20px; align-items: flex-start; margin-bottom: 23px; }
h1 { font-size: 24px; line-height: 1.2; letter-spacing: -.35px; margin: 0 0 5px; font-weight: 650; }
.page-heading p { color: var(--muted); margin: 0; }
.heading-actions { display: flex; align-items: center; gap: 9px; }
select, .button { border: 1px solid #cbd5e1; background: #fff; border-radius: 4px; color: #334155; padding: 8px 12px; }
.button { cursor: pointer; font-weight: 600; }
.button.primary { background: var(--blue); border-color: var(--blue); color: #fff; }
.button:hover { filter: brightness(.98); }
.metrics { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-bottom: 18px; }
.card { background: var(--panel); border: 1px solid var(--line); border-radius: 6px; box-shadow: var(--shadow); }
.metric { padding: 19px 20px; }
.metric-label { color: var(--muted); font-size: 13px; font-weight: 600; }
.metric-value { font-size: 28px; line-height: 1.2; font-weight: 650; letter-spacing: -.5px; margin: 8px 0 8px; }
.metric-note { color: var(--muted); font-size: 12px; display: flex; align-items: center; gap: 7px; }
.change { font-weight: 650; padding: 2px 6px; border-radius: 3px; }
.change.positive { background: var(--green-soft); color: var(--green); }
.change.neutral { background: var(--blue-soft); color: #1d4ed8; }
.grid-main { display: grid; grid-template-columns: minmax(0, 1.45fr) minmax(310px, .85fr); gap: 18px; align-items: start; }
.panel-header { display: flex; align-items: center; justify-content: space-between; padding: 17px 20px; border-bottom: 1px solid var(--line); }
.panel-title { margin: 0; font-size: 15px; font-weight: 650; }
.panel-meta { color: var(--muted); font-size: 12px; }
.chart-wrap { padding: 18px 18px 12px; }
.chart-holder { position: relative; width: 100%; height: 295px; }
#revenue-chart { width: 100%; height: 100%; display: block; overflow: visible; }
.chart-footer { display: flex; justify-content: space-between; color: var(--muted); font-size: 11px; padding: 7px 4px 0; }
.legend { display: flex; gap: 7px; align-items: center; color: var(--muted); font-size: 12px; }
.legend-dot { width: 8px; height: 8px; background: var(--blue); border-radius: 50%; }
.products { margin-top: 18px; }
.table-wrap { overflow-x: auto; }
table { border-collapse: collapse; width: 100%; }
th, td { padding: 12px 20px; text-align: left; border-bottom: 1px solid #edf1f5; }
th { color: var(--muted); font-size: 11px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; }
td { font-size: 13px; }
tbody tr:last-child td { border-bottom: 0; }
.product-cell { display: flex; align-items: center; gap: 10px; font-weight: 600; }
.product-thumb { width: 30px; height: 30px; border-radius: 4px; display: grid; place-items: center; color: #334e68; background: #e6eef7; font-size: 12px; font-weight: 700; }
.units { color: #334155; font-weight: 600; }
.activity-list { list-style: none; padding: 5px 20px 5px; margin: 0; }
.activity-item { display: grid; grid-template-columns: 29px minmax(0, 1fr); gap: 11px; padding: 13px 0; border-bottom: 1px solid #edf1f5; }
.activity-item:last-child { border-bottom: 0; }
.activity-icon { width: 28px; height: 28px; border-radius: 50%; display: grid; place-items: center; font-size: 12px; font-weight: 700; }
.activity-icon.order { color: #1d4ed8; background: #eff6ff; }
.activity-icon.refund { color: var(--red); background: var(--red-soft); }
.activity-icon.review { color: var(--amber); background: var(--amber-soft); }
.activity-line { display: flex; justify-content: space-between; gap: 8px; }
.activity-text { color: #334155; font-size: 12.5px; }
.activity-text strong { color: var(--text); font-weight: 650; }
.activity-time { color: var(--subtle); white-space: nowrap; font-size: 11px; }
.activity-detail { color: var(--muted); font-size: 11px; margin-top: 2px; }
.footer-note { color: var(--muted); font-size: 11px; margin-top: 17px; }
@media (max-width: 1020px) { .app { grid-template-columns: 68px minmax(0, 1fr); } .sidebar { padding: 22px 9px; } .brand { padding: 0 10px 28px; } .brand span, .section-label, .nav-link span { display: none; } .nav-link { justify-content: center; padding: 10px; } .nav-icon { font-size: 16px; } }
@media (max-width: 760px) { .topbar { padding: 0 18px; } .content { padding: 22px 18px 34px; } .page-heading { display: block; } .heading-actions { margin-top: 16px; } .metrics { grid-template-columns: 1fr; gap: 10px; } .grid-main { grid-template-columns: 1fr; } .top-actions .profile-name, .top-actions .profile-role { display: none; } }

