margin-top:28px;
color:#172b4d;margin-left:5px

    :root {
      --navy: #17324d;
      --navy-dark: #10263b;
      --blue: #2f6f9f;
      --blue-light: #eaf2f8;
      --text: #243444;
      --muted: #66788a;
      --border: #d9e1e8;
      --surface: #ffffff;
      --background: #f4f6f8;
      --green: #2c7a57;
      --green-bg: #e8f4ed;
      --red: #a64b4b;
      --red-bg: #f8ebeb;
      --amber: #9a6b22;
      --amber-bg: #fbf3e3;
      --shadow: 0 1px 2px rgba(25, 45, 65, .06);
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      background: var(--background);
      color: var(--text);
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif;
      font-size: 14px;
      line-height: 1.45;
    }
    .app { min-height: 100vh; }
    .topbar {
      height: 64px;
      background: var(--navy);
      color: white;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 32px;
    }
    .brand { display: flex; align-items: center; gap: 12px; }
    .brand-mark {
      width: 29px; height: 29px; border: 2px solid #c8d9e7; border-radius: 4px;
      display: grid; place-items: center; font-weight: 700; font-size: 13px;
    }
    .brand-name { font-size: 16px; font-weight: 600; letter-spacing: .1px; }
    .topbar-right { display: flex; align-items: center; gap: 18px; color: #dbe7f0; }
    .store-label { font-size: 13px; }
    .avatar {
      width: 30px; height: 30px; border-radius: 50%; background: #dce8f0; color: var(--navy);
      display: grid; place-items: center; font-size: 12px; font-weight: 700;
    }
    .layout { display: flex; min-height: calc(100vh - 64px); }
    .sidebar {
      width: 220px; background: #fff; border-right: 1px solid var(--border); padding: 22px 14px;
      flex: 0 0 220px;
    }
    .nav-section { margin-bottom: 26px; }
    .nav-heading {
