* { box-sizing:border-box; }
body { margin:0; background:var(--canvas); color:var(--ink); font:14px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; }
.shell { max-width:1360px; margin:auto; padding:30px; }
header { display:flex; align-items:center; justify-content:space-between; margin-bottom:28px; }
.brand { display:flex; align-items:center; gap:12px; font-weight:750; font-size:18px; letter-spacing:-.02em; }
.mark { width:34px; height:34px; display:grid; place-items:center; background:var(--green); color:#fff; border-radius:10px; font-size:18px; }
