width:72%

:root {
  --color-ink: #17211f;
  --color-muted: #52625e;
  --color-page: #f5f7f3;
  --color-surface: #ffffff;
  --color-border: #d8e1dc;
  --color-primary: #176b55;
  --color-primary-dark: #0e4e3d;
  --color-primary-pale: #e3f3ec;
  --color-positive: #11613f;
  --color-positive-pale: #e5f5ec;
  --color-negative: #a12c3d;
  --color-negative-pale: #fbeaec;
  --color-gold: #a45b08;
  --shadow-card: 0 0.4rem 1.4rem rgba(25, 50, 41, 0.08);
  --radius-lg: 1rem;
  --radius-md: 0.75rem;
  --radius-sm: 0.5rem;
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.5rem;
  --space-6: 2rem;
  --space-7: 3rem;
  --font-sans: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

* { box-sizing: border-box; }

html { color-scheme: light; }

body {
  min-width: 20rem;
  margin: 0;
  background: var(--color-page);
  color: var(--color-ink);
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.5;
}

button, select { font: inherit; }

button, select, a { -webkit-tap-highlight-color: transparent; }

:focus-visible {
  outline: 0.2rem solid #134e9e;
  outline-offset: 0.2rem;
}

.skip-link {
  position: fixed;
  z-index: 10;
  top: -4rem;
  left: var(--space-4);
  padding: var(--space-3) var(--space-4);
  border-radius: var(--radius-sm);
  background: var(--color-ink);
  color: #fff;
  text-decoration: none;
}

.skip-link:focus { top: var(--space-4); }

.site-header {
  border-bottom: 1px solid var(--color-border);
  background: var(--color-surface);
}

.header__inner, .dashboard, .footer__inner {
  width: min(100% - 2rem, 78rem);
  margin-inline: auto;
}

.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  min-height: 4.75rem;
}

.brand {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  color: var(--color-ink);
  font-weight: 800;
  letter-spacing: -0.02em;
  text-decoration: none;
}

.brand__mark {
  display: grid;
  width: 2.25rem;
  height: 2.25rem;
  place-items: center;
  border-radius: 50%;
  background: var(--color-primary);
  color: #fff;
  font-size: 1.1rem;
}

.header__status {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  color: var(--color-muted);
  font-size: 0.875rem;
}

.status-dot {
  width: 0.625rem;
  height: 0.625rem;
  border-radius: 50%;
  background: var(--color-positive);
}

.dashboard { padding-block: var(--space-6) var(--space-7); }

.page-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: var(--space-4);
  margin-bottom: var(--space-6);
}

.eyebrow {
  margin: 0 0 var(--space-1);
  color: var(--color-primary-dark);
  font-size: 0.8125rem;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

h1, h2, h3, p { margin-top: 0; }

h1 {
  margin-bottom: 0;
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  line-height: 1.15;
  letter-spacing: -0.04em;
}

h2 {
  margin-bottom: 0;
  font-size: 1.125rem;
  line-height: 1.3;
  letter-spacing: -0.015em;
}

h3 {
  margin-bottom: var(--space-1);
  font-size: 0.9375rem;
  line-height: 1.3;
}

.date-stamp { margin: 0; color: var(--color-muted); font-size: 0.875rem; white-space: nowrap; }

.metrics {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr);
  gap: var(--space-4);
  margin-bottom: var(--space-4);
}

.card {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  background: var(--color-surface);
  box-shadow: var(--shadow-card);
}

.metric-card { padding: var(--space-5); }

.metric-card__label { margin: 0 0 var(--space-3); color: var(--color-muted); font-size: 0.9375rem; font-weight: 700; }

.metric-card__value {
  margin: 0 0 var(--space-2);
  font-size: clamp(2rem, 5vw, 2.75rem);
  font-weight: 800;
  letter-spacing: -0.05em;
  line-height: 1;
}

.metric-card__detail { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2); margin: 0; color: var(--color-muted); font-size: 0.875rem; }

.trend {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  padding: 0.2rem 0.45rem;
  border-radius: var(--radius-sm);
  font-weight: 800;
  white-space: nowrap;
}

.trend--up { background: var(--color-positive-pale); color: var(--color-positive); }
.trend--down { background: var(--color-negative-pale); color: var(--color-negative); }

.dashboard-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(19rem, 1fr);
  gap: var(--space-4);
