    h3 {
      margin-bottom: 0.15rem;
      font-size: 0.95rem;
      line-height: 1.35;
    }

    .period-control {
      display: flex;
      flex-direction: column;
      gap: var(--space-1);
      min-width: 11rem;
      color: var(--color-muted);
      font-size: 0.8125rem;
      font-weight: 700;
    }

    .period-control__select {
      padding: 0.55rem 2rem 0.55rem 0.7rem;
      border: 1px solid var(--color-line);
      border-radius: var(--radius-medium);
      background: var(--color-surface);
      color: var(--color-ink);
      cursor: pointer;
      font-size: 0.9375rem;
      font-weight: 600;
    }

    .metrics {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: var(--space-4);
      margin-bottom: var(--space-5);
    }

    .card {
      border: 1px solid var(--color-line);
      border-radius: var(--radius-large);
      background: var(--color-surface);
      box-shadow: var(--shadow-card);
    }

    .metric-card { padding: var(--space-5); }

    .metric-card__label {
      margin-bottom: var(--space-3);
      color: var(--color-muted);
      font-size: 0.875rem;
      font-weight: 700;
    }

    .metric-card__value {
      margin-bottom: var(--space-2);
      font-size: clamp(1.75rem, 4vw, 2.25rem);
      font-weight: 800;
      letter-spacing: -0.045em;
      line-height: 1;
    }

    .metric-card__note {
      display: flex;
      align-items: center;
      gap: var(--space-2);
      margin: 0;
      color: var(--color-muted);
      font-size: 0.875rem;
    }

    .metric-card__badge {
      padding: 0.15rem 0.45rem;
      border-radius: 99rem;
      background: var(--color-success-soft);
      color: var(--color-success);
      font-size: 0.75rem;
      font-weight: 800;
      white-space: nowrap;
    }

    .metric-card__badge--neutral {
      background: var(--color-brand-soft);
      color: var(--color-brand-dark);
    }

    .dashboard-grid {
      display: grid;
      grid-template-columns: minmax(0, 1.55fr) minmax(18rem, 1fr);
      gap: var(--space-4);
      align-items: start;
    }

    .dashboard-grid__secondary {
      display: grid;
      gap: var(--space-4);
    }

    .panel { padding: var(--space-5); }

    .panel__header {
      display: flex;
      align-items: start;
      justify-content: space-between;
      gap: var(--space-3);
      margin-bottom: var(--space-5);
    }

    .panel__subheading {
      margin: var(--space-1) 0 0;
      color: var(--color-muted);
      font-size: 0.875rem;
    }

    .chart-summary {
      color: var(--color-brand-dark);
      font-size: 0.875rem;
      font-weight: 800;
      text-align: right;
    }

    .chart-summary__label { display: block; color: var(--color-muted); font-size: 0.75rem; font-weight: 700; }

    .chart {
      position: relative;
      min-height: 19rem;
    }

    .chart__canvas {
      display: block;
      width: 100%;
      height: 19rem;
    }

    .chart__tooltip {
      position: absolute;
      z-index: 1;
      display: none;
      max-width: 10rem;
      padding: 0.4rem 0.55rem;
      transform: translate(-50%, calc(-100% - 0.6rem));
      border-radius: 0.4rem;
      background: var(--color-ink);
      color: #fff;
      font-size: 0.75rem;
      font-weight: 700;
      pointer-events: none;
      white-space: nowrap;
    }

    .chart__tooltip::after {
      position: absolute;
      bottom: -0.3rem;
      left: 50%;
      width: 0;
      height: 0;
      transform: translateX(-50%);
      border-top: 0.35rem solid var(--color-ink);
      border-right: 0.35rem solid transparent;
      border-left: 0.35rem solid transparent;
      content: "";
    }

    .list { margin: 0; padding: 0; list-style: none; }

    .product-list { display: grid; gap: var(--space-3); }

    .product-list__item {
      display: grid;
      grid-template-columns: 2rem minmax(0, 1fr) auto;
      align-items: center;
      gap: var(--space-3);
    }

    .product-list__rank {
      display: grid;
      width: 2rem;
      height: 2rem;
      place-items: center;
      border-radius: 50%;
      background: var(--color-brand-soft);
      color: var(--color-brand-dark);
      font-size: 0.8125rem;
      font-weight: 800;
    }

    .product-list__name { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .product-list__category { display: block; color: var(--color-muted); font-size: 0.8125rem; }
    .product-list__units { color: var(--color-muted); font-size: 0.8125rem; text-align: right; white-space: nowrap; }
    .product-list__units strong { display: block; color: var(--color-ink); font-size: 0.9375rem; }

    .activity-list { display: grid; gap: 0; }

    .activity-list__item {
      position: relative;
      display: grid;
      grid-template-columns: 2.25rem minmax(0, 1fr);
      gap: var(--space-3);
      padding: 0 0 var(--space-4);
    }

    .activity-list__item:not(:last-child)::before {
      position: absolute;
      top: 2.25rem;
      bottom: 0.3rem;
      left: 1.08rem;
      width: 1px;
      background: var(--color-line);
      content: "";
    }

    .activity-list__icon {
      display: grid;
      width: 2.25rem;
      height: 2.25rem;
      place-items: center;
      border-radius: 50%;
      background: var(--color-brand-soft);
      color: var(--color-brand-dark);
      font-size: 1rem;
      font-weight: 900;
    }

    .activity-list__icon--refund { background: var(--color-danger-soft); color: var(--color-danger); }
    .activity-list__icon--review { background: var(--color-warning-soft); color: var(--color-warning); }
    .activity-list__content { padding-top: 0.05rem; }
    .activity-list__text { margin: 0; color: var(--color-ink); font-size: 0.875rem; }
    .activity-list__time { display: block; margin-top: 0.15rem; color: var(--color-muted); font-size: 0.75rem; }

    .panel__footer {
      margin: var(--space-2) 0 0;
      padding-top: var(--space-4);
      border-top: 1px solid var(--color-line);
      color: var(--color-muted);
      font-size: 0.8125rem;
    }

    .site-footer {
      width: min(calc(100% - 2rem), var(--max-width));
      margin: 0 auto;
      padding: 0 0 var(--space-6);
      color: var(--color-muted);
      font-size: 0.8125rem;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 52rem) {
      .dashboard-grid { grid-template-columns: 1fr; }
      .dashboard-grid__secondary { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    }

    @media (max-width: 38rem) {
      .site-header__inner { min-height: 4.2rem; }
      .header-status { display: none; }
      .dashboard { padding-top: var(--space-5); }
      .dashboard__intro { align-items: stretch; flex-direction: column; }
      .period-control { width: 100%; }
      .metrics, .dashboard-grid__secondary { grid-template-columns: 1fr; }
      .panel, .metric-card { padding: var(--space-4); }
      .chart-summary { font-size: 0.8125rem; }
    }

    @media (prefers-reduced-motion: no-preference) {
      .card { transition: box-shadow 160ms ease, transform 160ms ease; }
      .card:hover { box-shadow: 0 0.6rem 1.7rem rgba(27, 42, 76, 0.13); transform: translateY(-0.1rem); }
    }

display: none;
